/**
 * Resized copies of raster images under `/public/images/` and `/public/uploads/` are generated by
 * the `/resized/[size]/[...path]` endpoint. Each image is scaled down to fit the given box
 * while keeping its aspect ratio, like Hugo’s `Fit` image method. PNG images are converted to WebP,
 * because full-color PNG files are several times larger.
 */

export const RESIZABLE_IMAGE_REGEX = /^\/(?:images|uploads)\/.+\.(?:jpe?g|png|webp)$/i;

/**
 * Get the URL of a resized image.
 * @param {string} src Original image path, e.g. `/uploads/photo.jpg`.
 * @param {string} size Box size in the `{width}x{height}` format, e.g. `640x360`.
 * @returns {string} Resized image path, e.g. `/resized/640x360/uploads/photo.jpg`, or the
 * original path if the image cannot be resized. A PNG image gets a `.webp` extension after its own,
 * e.g. `/resized/640x360/uploads/chart.png.webp`, so that it can’t clash with `chart.webp`.
 */
export const getResizedImageURL = (src, size) =>
  RESIZABLE_IMAGE_REGEX.test(src)
    ? `/resized/${size}${src}${/\.png$/i.test(src) ? '.webp' : ''}`
    : src;

/**
 * Get the original image path from the path of a resized image.
 * @param {string} path Path of a resized image, e.g. `uploads/chart.png.webp`.
 * @returns {string} Original image path, e.g. `uploads/chart.png`.
 */
export const getOriginalImagePath = (path) => path.replace(/(\.png)\.webp$/i, '$1');

/**
 * Get the `src` and `srcset` attributes of a responsive image.
 * @param {string} src Original image path.
 * @param {[string, string]} sizes 1x and 2x box sizes.
 * @returns {{ src: string, srcset: string | undefined }} Attributes.
 */
export const getResponsiveImage = (src, [size1x, size2x]) => {
  if (!RESIZABLE_IMAGE_REGEX.test(src)) {
    return { src, srcset: undefined };
  }

  const src1x = getResizedImageURL(src, size1x);
  const src2x = getResizedImageURL(src, size2x);

  return { src: src1x, srcset: `${src1x}, ${src2x} 2x` };
};

/** Box sizes for the images in a post body. */
export const BODY_IMAGE_SIZES = /** @type {[string, string]} */ (['800x600', '1600x1200']);

/** Box sizes for the featured image of a post summary. */
export const SUMMARY_IMAGE_SIZES = /** @type {[string, string]} */ (['640x360', '1280x720']);

/** Box sizes for the featured image of a post. */
export const FEATURED_IMAGE_SIZES = /** @type {[string, string]} */ (['1280x720', '2560x1440']);
